<?php

namespace App\Models;

use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;

class Booking extends Model
{
    /**
     * The table associated with the model.
     * Firebase Data Connect creates tables matching the type name.
     */
    protected $table = 'Booking';

    /**
     * The primary key type (UUID auto-generated by Data Connect).
     */
    protected $keyType = 'string';
    public $incrementing = false;

    /**
     * Data Connect does not use Laravel's updated_at/created_at columns.
     */
    public $timestamps = false;

    protected $fillable = [
        'userId',
        'courtId',
        'startTime',
        'endTime',
        'status',
    ];

    protected function casts(): array
    {
        return [
            'startTime' => 'datetime',
            'endTime' => 'datetime',
            'createdAt' => 'datetime',
        ];
    }

    /**
     * The user who made this booking.
     */
    public function user(): BelongsTo
    {
        return $this->belongsTo(User::class, 'userId');
    }

    /**
     * The court this booking is for.
     */
    public function court(): BelongsTo
    {
        return $this->belongsTo(Court::class, 'courtId');
    }
}
